-- Origine des lignes modifiées en place, pour la migration de retour.
CREATE TABLE IF NOT EXISTS solazeroth_v3_annexes_origine_creatures SELECT entry, AIName, KillCredit1 FROM creature_template WHERE entry IN (13157, 5435, 3225, 3226, 3227, 3228);
