-- Quêtes des annexes.

-- Récompenses rangées dans la Collection, chrono, médailles, sans potion (v3_annexes.cpp).
DROP TABLE IF EXISTS solazeroth_v3_annexes;
CREATE TABLE solazeroth_v3_annexes (quete INT UNSIGNED NOT NULL PRIMARY KEY, cle VARCHAR(8) NOT NULL, insignes INT UNSIGNED NOT NULL, eclats INT UNSIGNED NOT NULL, bronze INT UNSIGNED NOT NULL, argent INT UNSIGNED NOT NULL, `or` INT UNSIGNED NOT NULL, depart VARCHAR(64) NOT NULL, potion INT UNSIGNED NOT NULL, objet_or INT UNSIGNED NOT NULL);
DROP TABLE IF EXISTS solazeroth_v3_annexes_composants;
CREATE TABLE solazeroth_v3_annexes_composants (quete INT UNSIGNED NOT NULL, objet INT UNSIGNED NOT NULL, nombre INT UNSIGNED NOT NULL, PRIMARY KEY (quete, objet));
DROP TABLE IF EXISTS solazeroth_v3_reliques;
CREATE TABLE solazeroth_v3_reliques (objet_monde INT UNSIGNED NOT NULL PRIMARY KEY, objet INT UNSIGNED NOT NULL, famille TINYINT UNSIGNED NOT NULL, composant INT UNSIGNED NOT NULL);
DROP TABLE IF EXISTS solazeroth_v3_vagues;
CREATE TABLE solazeroth_v3_vagues (vague TINYINT UNSIGNED NOT NULL, creature INT UNSIGNED NOT NULL, nombre TINYINT UNSIGNED NOT NULL, PRIMARY KEY (vague, creature));
CREATE TABLE IF NOT EXISTS acore_characters.solazeroth_v3_annexes_medailles (guid INT UNSIGNED NOT NULL, quete INT UNSIGNED NOT NULL, medaille TINYINT UNSIGNED NOT NULL, temps INT UNSIGNED NOT NULL, PRIMARY KEY (guid, quete));
CREATE TABLE IF NOT EXISTS acore_characters.solazeroth_v3_annexes_joueur (guid INT UNSIGNED NOT NULL PRIMARY KEY, carte TINYINT UNSIGNED NOT NULL DEFAULT 0, vague TINYINT UNSIGNED NOT NULL DEFAULT 0, temps INT UNSIGNED NOT NULL DEFAULT 0, jour INT UNSIGNED NOT NULL DEFAULT 0);

-- Parts de zone : genre 4, annexe rendue (la quête) ; genre 5, relique dans la Collection.
DELETE FROM solazeroth_v3_zone_parts WHERE genre IN (4, 5);
