INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, Flags, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910211, 2, -1, 0, 14, 4500, 0, 'La matriarche des scorpides', 'Tue la Matriarche des scorpides, dans la crevasse à l''est du champ des scorpides ouvriers.', 'Sarkoth avait une compagne, plus vieille et plus grosse. Elle niche dans la crevasse, à l''est du champ des ouvriers. Sa piqûre ronge l''armure, et quand elle souffre, ses ouvriers accourent. Reviens quand tu seras mieux équipé, si tu tiens à ta peau.', 'Retourne voir qui t''a confié cette tâche.', 910121, 1, 910020, 1);
INSERT INTO quest_template_addon (ID, PrevQuestID, SpecialFlags) VALUES (910211, 910006, 0);
