INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910211, 1, 'Elle est morte. La Vallée dormira mieux. Prends ceci, taillé dans sa chitine. Rangé dans ta Collection : 15 Insignes, 6 éclats cadavériques.');
