INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, Flags, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RewardItem1, RewardAmount1, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910212, 2, -1, 0, 14, 12500, 0, 'Le commandant de la garde', 'Tue le Commandant de la garde Zalaphil, au Donjon de Tiragarde.', 'AVIS DE RECHERCHE. Le Commandant de la garde Zalaphil tient le Donjon de Tiragarde. Il lève son rempart toutes les trente secondes et appelle ses marins quand il faiblit. Frappez fort entre deux remparts.', 'Retourne voir qui t''a confié cette tâche.', 910122, 1, 5809, 1);
