INSERT INTO quest_template (ID, QuestType, QuestLevel, MinLevel, QuestSortID, RewardMoney, Flags, LogTitle, LogDescription, QuestDescription, QuestCompletionLog, RequiredNpcOrGo1, RequiredNpcOrGoCount1) VALUES (910226, 2, -1, 0, 14, 4500, 0, 'L''assaut des remparts', 'Contre la montre : tue le Lieutenant Benedict moins de 6 min après le premier humain tué au donjon (argent 4 min 30, or 3 min 30).', 'Un assaut se mène vite. Le chrono part au premier humain tué dans le donjon : traverse la cour et la tour, et tue Benedict en moins de six minutes. En moins de trois minutes trente, je te donne mes bottes.', 'Retourne voir qui t''a confié cette tâche.', 3192, 1);
