INSERT INTO quest_offer_reward (ID, Emote1, RewardText) VALUES (910226, 1, 'Un vrai assaut. Reviens quand tu veux faire mieux. Rangé dans ta Collection : 15 Insignes, 6 éclats cadavériques. Médaille d''argent : récompenses ×1,5 ; d''or : ×2.');
